	"counter": "// A reactive counter: the signal is the state, the bindings follow it.\n// Change the label, add a second button — then press Run.\n\nimport std::reactive::Signal;\nimport std::ui::{ mount_root, view };\n\nfun main() {\n\tmount_root(\"app\", || {\n\t\tlet count = Signal::new(0);\n\t\tview(\"div\")\n\t\t\t.child(view(\"h2\").text(\"Counter\"))\n\t\t\t.child(view(\"button\").text(\"+1\").on(\"click\", || count.set(count.get() + 1)))\n\t\t\t.child(view(\"p\").bind_text(count.map(|n| i\"clicked {n} times\")))\n\t});\n}\n",
